package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; @Entity @Table(name="tenants") public class Tenant extends BaseEntity { @Column(nullable=false,unique=true,length=120) private String slug; @Column(nullable=false,length=200) private String name; @Column(nullable=false,length=30) private String status="ACTIVE"; protected Tenant(){} public Tenant(String slug,String name){this.slug=slug;this.name=name;} public String getSlug(){return slug;} public String getName(){return name;} public String getStatus(){return status;} }
